# spaCy Matcher Pattern for Imperfect Tense (L'imparfait)
# Target VERB or AUX tokens with morphological features Mood=Ind and Tense=Imp
pattern_imparfait_intro = [
    {
        "POS": {"IN": ["VERB", "AUX"]},
        "MORPH": {"IS_SUBSET": ["Mood=Ind", "Tense=Imp"]}
    }
]

# Pattern including optional trigger adverbs (toujours, souvent, d'habitude, autrefois)
pattern_imparfait_with_adverb_trigger = [
    {
        "POS": "ADV",
        "LEMMA": {"IN": ["toujours", "souvent", "d'habitude", "autrefois"]},
        "OP": "?"
    },
    {
        "POS": {"IN": ["VERB", "AUX"]},
        "MORPH": {"IS_SUBSET": ["Mood=Ind", "Tense=Imp"]}
    }
]

# Edge Cases & Disambiguation Rules:
# 1. Plus-que-parfait disambiguation:
#    If the auxiliary (avoir/être) is in the imperfect AND followed by a past participle (VerbForm=Part),
#    the structure represents the Plus-que-parfait (e.g., "j'avais mangé"), NOT simple Imparfait.
pattern_plus_que_parfait_exclusion = [
    {
        "POS": "AUX",
        "LEMMA": {"IN": ["avoir", "être"]},
        "MORPH": {"IS_SUBSET": ["Mood=Ind", "Tense=Imp"]}
    },
    {
        "POS": "ADV",
        "OP": "*"
    },
    {
        "POS": "VERB",
        "MORPH": "VerbForm=Part"
    }
]

# 2. Conditional vs. Imperfect disambiguation:
#    Stems ending in -r- with -ais/-ait/-aient (e.g., "parlerais") are Conditional Present (Mood=Cnd|Tense=Pres),
#    whereas simple imperfect uses the present stem (e.g., "parlais").

# spaCy Matcher Pattern for Futur Simple (Simple Future Tense)
pattern_futur_simple = [
    {
        "POS": {"IN": ["VERB", "AUX"]},
        "MORPH": {"IN": ["Mood=Ind|Tense=Fut", "Tense=Fut|VerbForm=Fin", "Tense=Fut"]}
    }
]

# Edge Case & Disambiguation Pattern: Futur Simple vs. Futur Proche (Auxiliary Aller + Infinitive)
pattern_futur_proche_disambiguation = [
    {
        "POS": "VERB",
        "LEMMA": "aller",
        "MORPH": {"IN": ["Mood=Ind", "Tense=Pres", "VerbForm=Fin"]}
    },
    {
        "POS": "ADV",
        "OP": "*"
    },
    {
        "POS": "VERB",
        "MORPH": "VerbForm=Inf"
    }
]

# spaCy Matcher Patterns for Time and Duration Expressions (depuis, pendant, il y a, dans)

# 1. Pattern for 'depuis' (Present Verb + depuis + Duration/Number/Noun)
pattern_depuis_present = [
    {
        "POS": {"IN": ["VERB", "AUX"]},
        "MORPH": {"IS_SUBSET": ["Mood=Ind", "Tense=Pres"]}
    },
    {
        "POS": "ADV",
        "OP": "*"
    },
    {
        "POS": "ADP",
        "LEMMA": "depuis"
    },
    {
        "POS": {"IN": ["NUM", "DET", "NOUN"]}
    }
]

# 2. Pattern for 'pendant' (Completed Duration with Passé Composé or Future)
pattern_pendant_duration = [
    {
        "POS": {"IN": ["VERB", "AUX"]}
    },
    {
        "POS": "ADP",
        "LEMMA": "pendant"
    },
    {
        "POS": {"IN": ["NUM", "DET", "NOUN"]}
    }
]

# 3. Pattern for temporal 'il y a' (Past Verb + il y a + Duration)
pattern_il_y_a_temporal = [
    {
        "POS": "PRON",
        "LEMMA": "il"
    },
    {
        "POS": "PRON",
        "LEMMA": "y"
    },
    {
        "POS": "VERB",
        "LEMMA": "avoir",
        "MORPH": {"IS_SUBSET": ["Mood=Ind", "Tense=Pres"]}
    },
    {
        "POS": {"IN": ["NUM", "DET", "NOUN"]}
    }
]

# 4. Pattern for temporal 'dans' (Future Delay: Future Verb + dans + Number/Time Noun)
pattern_dans_future_delay = [
    {
        "POS": {"IN": ["VERB", "AUX"]},
        "MORPH": {"IN": ["Tense=Fut", "Mood=Ind"]}
    },
    {
        "POS": "ADP",
        "LEMMA": "dans"
    },
    {
        "POS": {"IN": ["NUM", "DET"]}
    },
    {
        "POS": "NOUN",
        "LEMMA": {"IN": ["minute", "heure", "jour", "semaine", "mois", "an", "année"]}
    }
]

# Edge Cases & Disambiguation Rules:
# 1. Disambiguating Spatial vs. Temporal 'dans':
#    - Spatial 'dans' specifies physical locations (e.g., "dans la maison", "dans la rue").
#    - Temporal 'dans' expresses future delay and requires a temporal noun lemma
#      (minute, heure, jour, semaine, mois, an, année) or cardinal number.
# 2. Disambiguating Existential vs. Temporal 'il y a':
#    - Existential 'il y a' introduces nouns ("Il y a un livre sur la table").
#    - Temporal 'il y a' requires a preceding completed verb (Passé Composé) and a following time duration unit.
# 3. 'Depuis' Tense Constraint Disambiguation:
#    - 'Depuis' requires present tense for ongoing actions. Past tense with 'depuis' indicates
#      an action interrupted in the past (Imparfait + depuis), not a completed event.

# spaCy Matcher Patterns for Extended Negation (ne...jamais, ne...rien, ne...personne, ne...plus, ne...que)

# Pattern 1: Standard Extended Negation in Simple & Compound Tenses (Mid-Auxiliary Placement)
# Captures: ne/n' + [PRON] + VERB/AUX + jamais | rien | plus
pattern_extended_negation_standard = [
    {
        "POS": "ADV",
        "LEMMA": "ne"
    },
    {
        "POS": "PRON",
        "OP": "*"  # Optional direct/indirect/reflexive pronouns (e.g. ne me, ne l')
    },
    {
        "POS": {"IN": ["VERB", "AUX"]}
    },
    {
        "POS": {"IN": ["ADV", "PRON"]},
        "LEMMA": {"IN": ["jamais", "rien", "plus"]}
    }
]

# Pattern 2: Post-Participle Extended Negation (Passé Composé with personne / restrictive que)
# Captures: ne/n' + AUX + VERB (past participle) + personne | que
pattern_extended_negation_post_participle = [
    {
        "POS": "ADV",
        "LEMMA": "ne"
    },
    {
        "POS": "AUX"
    },
    {
        "POS": "VERB",
        "MORPH": {"IN": ["VerbForm=Part", "Tense=Past"]}
    },
    {
        "POS": {"IN": ["PRON", "NOUN", "SCONJ", "ADV"]},
        "LEMMA": {"IN": ["personne", "que"]}
    }
]

# Pattern 3: Subject Position Negation (personne ne... / rien ne...)
# Captures: Personne | Rien + ne + VERB/AUX
pattern_negation_subject_position = [
    {
        "POS": {"IN": ["PRON", "NOUN"]},
        "LEMMA": {"IN": ["personne", "rien"]}
    },
    {
        "POS": "ADV",
        "LEMMA": "ne"
    },
    {
        "POS": {"IN": ["VERB", "AUX"]}
    }
]

# Edge Cases & Disambiguation Rules:
# 1. "personne" Disambiguation (Noun vs. Pronoun):
#    - Noun: "une personne" / "la personne" (preceded by DET/ADJ, POS=NOUN) -> "C'est une gentille personne." (NOT negation).
#    - Negative Pronoun: preceded by "ne" or serving as negative subject -> "Je ne vois personne." / "Personne ne sait."
# 2. "plus" Disambiguation (Comparative vs. Negation):
#    - Comparative: "Il est plus grand que moi." (POS=ADV, no preceding "ne").
#    - Negation: "Il ne fume plus." (Preceded by "ne", meaning "no longer").
# 3. "que" Disambiguation (Conjunction vs. Restrictive Negation):
#    - Subordinating Conjunction: "Je thin que..." (POS=SCONJ).
#    - Restrictive Negation: Paired with "ne" before the verb -> "Il ne boit que de l'eau."

# spaCy Matcher Pattern for Interrogative Pronouns (lequel stem & contracted forms)
# Targets PRON tokens representing interrogative/relative pronouns: lequel, laquelle, lesquels, lesquelles,
# as well as contracted forms: auquel, auxquels, auxquelles, duquel, desquels.

# Single-token interrogative/contracted pronouns
pattern_interrogative_pronoun_single = [
    {
        "POS": {"IN": ["PRON", "DET"]},
        "LOWER": {"IN": [
            "lequel", "laquelle", "lesquels", "lesquelles",
            "auquel", "auxquels", "auxquelles",
            "duquel", "desquels"
        ]}
    }
]

# Two-token uncontracted prepositional compounds (à laquelle, de laquelle, de lesquels, de lesquelles)
pattern_interrogative_pronoun_compound = [
    {
        "POS": "ADP",
        "LOWER": {"IN": ["à", "de"]}
    },
    {
        "POS": {"IN": ["PRON", "DET"]},
        "LOWER": {"IN": ["laquelle", "lesquels", "lesquelles"]}
    }
]

# Disambiguation & Edge Cases Note:
# 1. spaCy POS tagger may assign either PRON or DET to 'lequel' variants depending on sentence position;
#    including POS: {"IN": ["PRON", "DET"]} prevents false negatives.
# 2. Interrogative vs. Relative Pronoun Disambiguation:
#    'lequel' can function as a relative pronoun in complex multi-clause sentences (e.g., 'le livre dans lequel...').
#    Interrogative usage is distinguished by clause-initial position, sentence-ending question marks (?),
#    or immediate follow-up by partitive prepositions ('de') or inverted verbs.

# spaCy Matcher Pattern for Direct Object Pronouns before Conjugated Verb (Simple Tenses)
pattern_cod_conjugated = [
    {
        "POS": "PRON",
        "LEMMA": {"IN": ["le", "la", "l'", "les", "me", "te", "nous", "vous"]},
        "MORPH": {"IS_SUBSET": ["PronType=Prs"]}
    },
    {
        "POS": {"IN": ["VERB", "AUX"]},
        "MORPH": {"IS_SUBSET": ["VerbForm=Fin"]}
    }
]

# spaCy Matcher Pattern for Direct Object Pronouns in Compound Tenses (Passé Composé)
pattern_cod_compound = [
    {
        "POS": "PRON",
        "LEMMA": {"IN": ["le", "la", "l'", "les", "me", "te", "nous", "vous"]},
        "MORPH": {"IS_SUBSET": ["PronType=Prs"]}
    },
    {
        "POS": "AUX",
        "LEMMA": {"IN": ["avoir", "être"]}
    },
    {
        "POS": "ADV",
        "OP": "*"
    },
    {
        "POS": "VERB",
        "MORPH": "VerbForm=Part"
    }
]

# spaCy Matcher Pattern for Direct Object Pronouns before Infinitive (Dual-Verb / Modal)
pattern_cod_infinitive = [
    {
        "POS": "PRON",
        "LEMMA": {"IN": ["le", "la", "l'", "les", "me", "te", "nous", "vous"]},
        "MORPH": {"IS_SUBSET": ["PronType=Prs"]}
    },
    {
        "POS": "VERB",
        "MORPH": "VerbForm=Inf"
    }
]

# Edge Cases & Disambiguation Rules:
# 1. Direct Object Pronoun (PRON) vs. Definite Article (DET) Disambiguation:
#    Tokens "le", "la", "l'", "les" serve as definite articles (DET) when preceding a NOUN, ADJ, or PROPN,
#    and as direct object pronouns (PRON) when preceding a VERB, AUX, or INF.
pattern_definite_article_exclusion = [
    {
        "POS": "DET",
        "LEMMA": {"IN": ["le", "la", "l'", "les"]}
    },
    {
        "POS": {"IN": ["NOUN", "ADJ", "PROPN"]}
    }
]

# 2. Reflexive Pronoun vs. Direct Object Pronoun Disambiguation:
#    Pronouns "me", "te", "nous", "vous", "se" with reflexive verbs (Reflex=Yes) function as reflexive pronouns,
#    whereas non-reflexive direct object transitives take PRON without Reflex=Yes.

# spaCy Matcher Patterns for Indirect Object Pronouns (COI: lui, leur, me, te, nous, vous)

# Pattern 1: Standard Pre-verbal COI (Subject + COI + VERB / AUX)
# Targets COI pronouns (me, te, lui, nous, vous, leur) preceding a finite verb or auxiliary
pattern_coi_preverbal = [
    {
        "POS": "PRON",
        "LEMMA": {"IN": ["me", "te", "lui", "nous", "vous", "leur"]},
        "MORPH": {"IN": ["PronType=Prs", "Case=Dat"]}
    },
    {
        "POS": {"IN": ["VERB", "AUX"]}
    }
]

# Pattern 2: COI Preceding Infinitive in Dual-Verb Constructions (Futur Proche / Modals)
# Targets: Modal/Auxiliary Verb + [ADV] + COI Pronoun + Infinitive (e.g., "va lui parler")
pattern_coi_infinitive = [
    {
        "POS": {"IN": ["VERB", "AUX"]}
    },
    {
        "POS": "ADV",
        "OP": "*"
    },
    {
        "POS": "PRON",
        "LEMMA": {"IN": ["me", "te", "lui", "nous", "vous", "leur"]}
    },
    {
        "POS": "VERB",
        "MORPH": "VerbForm=Inf"
    }
]

# Pattern 3: Affirmative Imperative COI (Verb-Pronoun with hyphen)
# Targets: Imperative Verb + Hyphen + COI Pronoun (moi, toi, lui, nous, vous, leur)
pattern_coi_imperative_affirmative = [
    {
        "POS": "VERB",
        "MORPH": {"IN": ["Mood=Imp", "VerbForm=Fin"]}
    },
    {
        "ORTH": "-"
    },
    {
        "POS": "PRON",
        "LEMMA": {"IN": ["moi", "toi", "lui", "nous", "vous", "leur"]}
    }
]

# Edge Cases & Disambiguation Rules:
# 1. "lui" Disambiguation (Indirect Object Pronoun vs. Stressed/Disjunctive Pronoun):
#    - COI Pronoun: Placed BEFORE a conjugated verb or infinitive, replacing "à + person" -> "Je lui parle." (POS=PRON, dep=iobj).
#    - Stressed / Disjunctive Pronoun: Placed AFTER a preposition (avec, pour, chez, sans, selon, etc.) -> "Je vais avec lui." / "C'est pour lui." (ADP + PRON).
#    - Disambiguation: Check preceding POS tag; if ADP precedes, it is a stressed pronoun, NOT a COI pronoun.

pattern_lui_stressed_exclusion = [
    {
        "POS": "ADP",
        "LEMMA": {"IN": ["avec", "pour", "chez", "sans", "selon", "à", "de", "vers", "entre"]}
    },
    {
        "POS": "PRON",
        "LEMMA": "lui"
    }
]

# 2. "leur" Disambiguation (Indirect Object Pronoun vs. Possessive Determiner):
#    - COI Pronoun: INVARIABLE (never takes an 's'), placed BEFORE a verb/auxiliary -> "Je leur parle." (POS=PRON).
#    - Possessive Determiner: Modifies a noun, takes plural '-s' before plural nouns -> "leur maison" / "leurs enfants" (POS=DET).
#    - Disambiguation: Filter by POS=="PRON" vs POS=="DET", or check if followed directly by NOUN/ADJ.

pattern_leur_possessive_exclusion = [
    {
        "POS": "DET",
        "LEMMA": "leur",
        "MORPH": "Poss=Yes"
    },
    {
        "POS": {"IN": ["NOUN", "ADJ"]}
    }
]

# 3. "me / te / nous / vous" Disambiguation (COI vs COD vs Reflexive Pronouns):
#    - Reflexive: Subject and pronoun share person/number with a pronominal verb -> "Je me lave." (Reflex=Yes).
#    - COD: Pronoun receives action directly without 'à' -> "Il me voit." (dep=obj / Direct).
#    - COI: Verb requires 'à' complement -> "Il me parle." (dep=iobj / Indirect).
